<?php
require_once 'conexao.php';
$token=$_GET['token']??'';$erro='';$msg='';$a=null;
if(!preg_match('/^[a-f0-9]{48}$/',$token))$erro='Link de agendamento inválido.';else try{$s=$pdo->prepare('SELECT a.*,p.nome profissional,p.especialidade FROM agendamentos a JOIN profissionais p ON p.id=a.profissional_id WHERE a.token=?');$s->execute([$token]);$a=$s->fetch();if(!$a)$erro='Agendamento não encontrado.';}catch(Throwable $e){$erro='Não foi possível consultar o agendamento agora.';}
if($a&&$_SERVER['REQUEST_METHOD']==='POST'){$acao=$_POST['acao']??'';try{if($acao==='confirmar'&&$a['status']==='agendado'){$s=$pdo->prepare("UPDATE agendamentos SET status='confirmado' WHERE id=? AND status='agendado'");$s->execute([$a['id']]);$a['status']='confirmado';$msg='Consulta confirmada com sucesso.';}elseif($acao==='cancelar'&&in_array($a['status'],['agendado','confirmado'],true)){$s=$pdo->prepare("UPDATE agendamentos SET status='cancelado' WHERE id=? AND status IN ('agendado','confirmado')");$s->execute([$a['id']]);$a['status']='cancelado';$msg='Consulta cancelada.';}else $erro='Essa ação não está disponível para o status atual.';}catch(Throwable $e){$erro='Não foi possível atualizar o agendamento. Tente novamente.';}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meu agendamento | Espaço Aura</title><link rel="stylesheet" href="css/style.css"></head><body><main class="success-page"><div class="success-card"><img class="card-logo" src="img/logo-aura-oficial.png" alt="Espaço Aura"><?php if($erro):?><div class="alert error" data-popup="1"><?=htmlspecialchars($erro)?></div><?php endif;?><?php if($msg):?><div class="alert success" data-popup="1"><?=htmlspecialchars($msg)?></div><?php endif;?><?php if($a):?><p class="eyebrow">MEU AGENDAMENTO</p><h1><?=htmlspecialchars($a['nome'])?></h1><div class="appointment-summary"><p><strong>Serviço:</strong> <?=htmlspecialchars($a['servico'])?></p><p><strong>Profissional:</strong> <?=htmlspecialchars($a['profissional'])?></p><p><strong>Data:</strong> <?=date('d/m/Y',strtotime($a['data']))?></p><p><strong>Horário:</strong> <?=substr($a['horario'],0,5)?></p><p><strong>Status:</strong> <?=htmlspecialchars($a['status'])?></p></div><?php if($a['status']==='agendado'):?><form method="post" class="inline-form"><input type="hidden" name="acao" value="confirmar"><button class="btn" type="submit">Confirmar consulta</button></form><?php endif;?><?php if(in_array($a['status'],['agendado','confirmado'],true)):?><form method="post" class="inline-form" data-confirm="Deseja cancelar este agendamento?"><input type="hidden" name="acao" value="cancelar"><button class="btn-danger" type="submit">Cancelar consulta</button></form><?php endif;?><?php endif;?><div class="space-top"><a href="index.php" class="back-link">Voltar ao site</a></div></div></main><script src="js/app.js"></script></body></html>
